  create policy "clothes_crud_own_data"
  on "public"."clothes"
  as permissive
  for all
  to authenticated
using ((auth.uid() = user_id))
with check ((auth.uid() = user_id));



  create policy "clothes_tags_crud_own_data"
  on "public"."clothes_tags"
  as permissive
  for all
  to authenticated
using ((EXISTS ( SELECT 1
   FROM public.clothes c
  WHERE ((c.id = clothes_tags.clothes_id) AND (c.user_id = auth.uid())))))
with check ((EXISTS ( SELECT 1
   FROM public.clothes c
  WHERE ((c.id = clothes_tags.clothes_id) AND (c.user_id = auth.uid())))));



  create policy "tags_select_authenticated"
  on "public"."tags"
  as permissive
  for select
  to authenticated
using (true);



